281   * hb_subset:
   282   * @source: font face data to be subset.
   283   * @input: input to use for the subsetting.
   284   *
   285   * Subsets a font according to provided input.
   286   **/
   287  hb_face_t *
   288  hb_subset (hb_face_t *source,
   289             hb_subset_input_t *input)
   290  {
   291    if (unlikely (!input || !source)) return hb_face_get_empty ();
   292
   293    hb_subset_plan_t *plan = hb_subset_plan_create (source, input);
   294
   295    hb_tag_t table_tags[32];
   296    unsigned int offset = 0, count;
   297    bool success = true;
   298    do {
   299      count = ARRAY_LENGTH (table_tags);
   300      hb_face_get_table_tags (source, offset, &count, table_tags);
   301      for (unsigned int i = 0; i < count; i++)
   302      {
   303        hb_tag_t tag = table_tags[i];
   304        if (_should_drop_table (plan, tag))
   305        {
   306          DEBUG_MSG(SUBSET, nullptr, "drop %c%c%c%c", HB_UNTAG (tag));
   307          continue;
   308        }
   309        success = success && _subset_table (plan, tag);
   310      }
   311      offset += count;
   312    } while (success && count == ARRAY_LENGTH (table_tags));
   313
   314    hb_face_t *result = success ? hb_face_reference (plan->dest) : hb_face_get_empty ();
   315    hb_subset_plan_destroy (plan);
   316    return result;
   317  }
